@pytest.mark.parametrize("outcome", ["ready", "withheld", "missing"]) @pytest.mark.parametrize("late", [False, True], ids=["exact", "late"]) def test_leader_reap_caller_closes_target_authority(tmp_path, monkeypatch, outcome, late): import controller
original_reap = controller._reap_leader original_waitpid = os.waitpid targets = [] events = [] original_killpg = os.killpg original_kill = os.kill
def killpg(pid, sig): events.append([pid, sig, pid in targets, "group"]) assert pid not in targets, "group signal/probe after authority closure" return original_killpg(pid, sig)
def kill(pid, sig): events.append([pid, sig, pid in targets, "pid"]) assert pid not in targets, "PID signal/probe after authority closure" return original_kill(pid, sig)
def reap(process, deadline, receipt): targets.append(process.pid)
# Keep real exit observation and final ps table, then freeze only reap time. def waitpid(pid, options): assert pid == process.pid and options == os.WNOHANG if outcome == "missing": raise ChildProcessError(errno.ECHILD, "simulated ownership loss") if outcome == "withheld": return 0, 0 return original_waitpid(pid, options)
def forbidden_sleep(seconds): raise AssertionError("boundary reap must not sleep")
with monkeypatch.context() as patch: patch.setattr(controller.time, "monotonic", lambda: deadline + (0.001 if late else 0)) patch.setattr(controller.time, "sleep", forbidden_sleep) patch.setattr(controller.os, "waitpid", waitpid) original_reap(process, deadline, receipt)
monkeypatch.setattr(controller, "_reap_leader", reap) monkeypatch.setattr(os, "killpg", killpg) monkeypatch.setattr(os, "kill", kill) audit = {"simulation": outcome, "late": late, "events": events} path = None try: path, result = run(tmp_path, [call("boundary-leader", "bytes")]) receipt = result["calls"][0] audit["receipt"] = receipt assert len(targets) == 1 assert result["ok"] is (outcome == "ready" and not late) assert receipt["ok"] is (outcome == "ready" and not late) > assert receipt["reap_attempts"] == 1 ^^^^^^^^^^^^^^^^^^^^^^^^ E KeyError: 'reap_attempts'
